  out.innerHTML = 'Your phone reaches Cloudflare at <b>' + res.edge + '</b>: median <b>' + res.http.p50 + ' ms</b><br>'
    + 'Table server runs at <b>' + res.table + '</b>: live median <b>' + res.live.p50 + ' ms</b>, 95th percentile <b>' + res.live.p95 + ' ms</b><br>'
